// #define REG_ACCESS_OPT //currently, not need such flow, not much gain
#ifdef REG_ACCESS_OPT
/* { SWREG, BITS, POSITION, WRITABLE } */
typedef struct {
  u16 reg_id;
  u8  bits;   //bit_num
  u8  posi;   //bit offset in swreg

  u8  rw;     //0: read only; 1: read + write
} HwRegDesc;

#define G2REG(reg_id, bits, posi, rw) {reg_id, bits, posi, rw}

#else

typedef struct {
  u16 reg_id;
  u8  bits;   //bit_num
  u8  posi;   //bit offset in swreg
} HwRegDesc;

#define G2REG(reg_id, bits, posi, rw) {reg_id, bits, posi}

#endif

extern const HwRegDesc hw_dec_reg_spec[HWIF_LAST_REG + 1];

/*------------------------------------------------------------------------------
    Data types
------------------------------------------------------------------------------*/

/*------------------------------------------------------------------------------
    Function prototypes
------------------------------------------------------------------------------*/

void SetDecRegister(u32* reg_base, u32 id, u32 value);
u32 GetDecRegister(const u32* reg_base, u32 id);
void FlushDecRegisters(const void* dwl, i32 core_id, u32* regs, u32 max_regs);
void RefreshDecRegisters(const void* dwl, i32 core_id, u32* regs, u32 max_regs);
void SetPpuRegister(u32 *pp_reg_base, u32 id, int ppu_index, u32 value);
u32 GetPpuRegister(const u32 *pp_reg_base, u32 id, int ppu_index);

/* G1&G2 */
#define SET_ADDR_REG(reg_base, REGBASE, addr) do {\
    SetDecRegister((reg_base), REGBASE##_LSB, (u32)(addr));  \
    if (hw_feature->addr64_support) { \
      if(sizeof(addr_t) == 4) \
        SetDecRegister((reg_base), REGBASE##_MSB, 0); \
      else \
        SetDecRegister((reg_base), REGBASE##_MSB, (u32)((u64)(addr) >> 32)); \
    } else { \
      if(sizeof(addr_t) == 8) \
        ASSERT(((u32)((u64)(addr) >> 32)) == 0); \
    } \
  } while (0)

/* for both G1&G2 */
#define SET_ADDR_REG2(reg_base, lsb, msb, addr) do {\
    SetDecRegister((reg_base), (lsb), (u32)(addr));  \
    if (hw_feature->addr64_support) { \
      SetDecRegister((reg_base), (msb), (u32)((u64)(addr) >> 32)); \
    } else { \
      ASSERT((u32)((u64)(addr) >> 32) == 0); \
      SetDecRegister((reg_base), (msb), 0); \
    } \
  } while (0)

/* only used in cmodel */
#define SET_ADDR_REG3(reg_base, REGBASE, addr, addr64_support) do {\
    SetDecRegister((reg_base), REGBASE##_LSB, (u32)(addr));  \
    if (addr64_support) { \
      if(sizeof(addr_t) == 4) \
        SetDecRegister((reg_base), REGBASE##_MSB, 0); \
      else \
        SetDecRegister((reg_base), REGBASE##_MSB, (u32)((u64)(addr) >> 32)); \
    } else { \
      if(sizeof(addr_t) == 8) \
        ASSERT(((u32)((u64)(addr) >> 32)) == 0); \
    } \
  } while (0)

#define SET_PP_ADDR_REG(reg_base, REGBASE, addr) do {\
    SetDecRegister((reg_base), REGBASE, (u32)(addr));  \
    if (hw_feature->addr64_support) { \
      SetDecRegister((reg_base), REGBASE##_MSB, (u32)((u64)(addr) >> 32)); \
    } else { \
      assert((u32)((u64)(addr) >> 32) == 0); \
    } \
  } while (0)

#define SET_PP_ADDR_REG2(reg_base, lsb, msb, i, addr) do {\
    SetPpuRegister((reg_base), (lsb), (i), (u32)(addr));  \
    if (hw_feature->addr64_support) { \
      SetPpuRegister((reg_base), (msb), (i), (u32)((u64)(addr) >> 32)); \
    } else { \
      assert((u32)((u64)(addr) >> 32) == 0); \
      SetPpuRegister((reg_base), (msb), (i), 0); \
    } \
  } while (0)

#define SET_ADDR64_REG(reg_base, REGBASE, addr) do {\
    SetDecRegister((reg_base), REGBASE##_LSB, (u32)(addr));  \
    if (hw_feature->addr64_support) { \
      SetDecRegister((reg_base), REGBASE##_MSB, (u32)((addr_t)(addr) >> 32)); \
    } else { \
      assert((u32)((addr_t)(addr) >> 32) == 0); \
      SetDecRegister((reg_base), REGBASE##_MSB, 0); \
    } \
  } while (0)

#define GET_ADDR_REG(reg_base, REGBASE)  \
    (sizeof(addr_t) == 8 ? \
    (((addr_t)GetDecRegister((reg_base), REGBASE##_LSB)) |  \
    (((addr_t)GetDecRegister((reg_base), REGBASE##_MSB)) << 32)) \
    :(GetDecRegister((reg_base), REGBASE##_LSB)))

#define GET_ADDR_REG2(reg_base, lsb, msb)  \
    (sizeof(addr_t) == 8 ? \
    (((addr_t)GetDecRegister((reg_base), (lsb))) |  \
    (((addr_t)GetDecRegister((reg_base), (msb))) << 32)) \
    : (GetDecRegister((reg_base), (lsb))))

#define GET_PP_ADDR_REG(reg_base, REGBASE)  \
    (sizeof(addr_t) == 8 ? \
    (((addr_t)GetPpRegister((reg_base), REGBASE)) |  \
    (((addr_t)GetPpRegister((reg_base), REGBASE##_MSB)) << 32)) \
    : (GetDecRegister((reg_base), REGBASE)))

#define GET_PP_ADDR64_REG(reg_base, REGBASE, i)  \
      (sizeof(addr_t) == 8 ? \
      (((addr_t)GetPpuRegister((reg_base), REGBASE##_LSB, (i))) |  \
      (((addr_t)GetPpuRegister((reg_base), REGBASE##_MSB, (i))) << 32)) \
      :(GetPpuRegister((reg_base), REGBASE##_LSB, (i))))

#define GET_PP_ADDR_REG2(reg_base, lsb, msb, i)  \
    (sizeof(addr_t) == 8 ? \
    (((addr_t)GetPpuRegister((reg_base), (lsb), (i))) |  \
    (((addr_t)GetPpuRegister((reg_base), (msb), (i))) << 32)) \
    :(GetPpuRegister((reg_base), (lsb), (i))))

#define GET_ADDR64_REG(reg_base, REGBASE)  \
  (sizeof(addr_t) == 8 ? \
  (((addr_t)GetDecRegister((reg_base), REGBASE##_LSB)) |  \
  (((addr_t)GetDecRegister((reg_base), REGBASE##_MSB)) << 32)) \
  :(GetDecRegister((reg_base), REGBASE##_LSB)))

/* below only used in cmodel*/

#define PTR_TO_ADDR(ptr) (addr_t)(size_t)(ptr)

// GET_ADDR_REG
#define ADDR_REG_TO_PTR(reg_base, REGBASE)  \
    (sizeof(size_t) == 8 ? \
    (((size_t)GetDecRegister((reg_base), REGBASE##_LSB)) |  \
    (((size_t)GetDecRegister((reg_base), REGBASE##_MSB)) << 32)) \
    :((size_t)GetDecRegister((reg_base), REGBASE##_LSB)))

// GET_ADDR_REG2
#define ADDR_REG_TO_PTR2(reg_base, lsb, msb)  \
    (sizeof(size_t) == 8 ? \
    (((size_t)GetDecRegister((reg_base), (lsb))) |  \
    (((size_t)GetDecRegister((reg_base), (msb))) << 32)) \
    : ((size_t)GetDecRegister((reg_base), (lsb))))

// GET_PP_ADDR64_REG
#define PP_ADDR64_REG_TO_PTR(reg_base, REGBASE, i)  \
      (sizeof(size_t) == 8 ? \
      (((size_t)GetPpuRegister((reg_base), REGBASE##_LSB, (i))) |  \
      (((size_t)GetPpuRegister((reg_base), REGBASE##_MSB, (i))) << 32)) \
      :((size_t)GetPpuRegister((reg_base), REGBASE##_LSB, (i))))

// GET_PP_ADDR_REG2
#define PP_ADDR_REG_TO_PTR2(reg_base, lsb, msb, i)  \
    (sizeof(size_t) == 8 ? \
    (((size_t)GetPpuRegister((reg_base), (lsb), (i))) |  \
    (((size_t)GetPpuRegister((reg_base), (msb), (i))) << 32)) \
    :((size_t)GetPpuRegister((reg_base), (lsb), (i))))

// GET_ADDR64_REG
#define ADDR64_REG_TO_PTR(reg_base, REGBASE)  \
  (sizeof(size_t) == 8 ? \
  (((size_t)GetDecRegister((reg_base), REGBASE##_LSB)) |  \
  (((size_t)GetDecRegister((reg_base), REGBASE##_MSB)) << 32)) \
  :((size_t)GetDecRegister((reg_base), REGBASE##_LSB)))

typedef struct {
  u32 codec;
  u32 format;
  u32 display_width;
  u32 display_height;
  u32 decode_width;
  u32 decode_height;
  u32 frame_type[20];
  u32 scan_count;
  u32 slice_num[10];
  u32 pp_input_luma_size;
  u32 chroma_format_id;
  u8 depth_flag;
  u8 resolution_flag;
  u8 chroma_flag;
  u8 bit_depth;
  u32 frame_num;
  u8 crop_flag;
  u32 bitrate;
  u8 b_slice_flag;
  u8 p_slice_flag;
  u8 interlace_flag;
  u8 intrabc_flag;
  u8 tile_flag;
  u8 aso_flag;
  u8 fmo_flag;
  u8 pjpeg_flag;
  u8 thumb_flag;
  u8 cavlc_flag;
  u8 interintra;
  u8 palette_mode;
  u8 filter_intra_pred;
  u8 intra_edge_filter;
  u32 show_existing_frame;
  u32 fieldmode[10];
  u32 fieldpic_flag[10];
  u32 num_tile_cols_8k[10];
  u32 blackwhite_e[10];
  u32 bit_depth_y_minus8[10];
  u32 bit_depth_c_minus8[10];
  u32 ppin_luma_size[10];
  u32 pic_width_in_cbs;
  u32 pic_height_in_cbs;
  u32 min_cb_size;
  u32 max_cb_size;
  u32 crop_x;
  u32 crop_y;
}CaseInfo;

enum{
  I_FRAME,
  B_FRAME,
  P_FRAME,
  GB_FRAME,
  F_FRAME,
  S_FRAME,
  G_FRAME,
  FI_FRAME,
  BI_FRAME,
  FIELD_I_I,
  FIELD_I_P,
  FIELD_P_I,
  FIELD_P_P,
  FIELD_B_B,
  FIELD_B_BI,
  FIELD_BI_B,
  FIELD_BI_BI,
  I_FIELED_0,
  P_FIELED_0,
  B_FIELED_0,
  I_FIELED_1,
  P_FIELED_1,
  B_FIELED_1,
};

extern CaseInfo case_info;
/* Used for Base Decoder: only be called once. */
void VCDecInfoCollect(CaseInfo* case_info);

CaseInfo case_info;

static void WriteInfo(u32* info, u32 num,  FILE* caseprint) {
  u8 i = 0;

  if(num == 0) {
    fprintf(caseprint, "%s", " |");
    return;
  }
  for(i = 0; i < num ;i++) {
    if(i == 0)
      fprintf(caseprint, "%s", "[");
    if(i == 0 && num == 1)
      fprintf(caseprint, "%u%s|",info[i], "]");
    else if(i == num - 1)
      fprintf(caseprint,"%u%s|", info[i],"]");
    else
      fprintf(caseprint,"%u,", info[i]);
  }
}

static void GetFormatString(CaseInfo* case_info, char* f) {
  switch(case_info->format) {
    case DEC_MPEG4:
      if(!case_info->codec)  case_info->codec = DEC_MODE_MPEG4;
      sprintf(f, "%s", "mpeg4");
      break;
    case DEC_MPEG2:
      if(!case_info->codec)  case_info->codec = DEC_MODE_MPEG2;
      sprintf(f, "%s", "mpeg2");
      break;
    case DEC_VP6:
      if(!case_info->codec)  case_info->codec = DEC_MODE_VP6;
      sprintf(f, "%s", "vp6");
      break;
    case DEC_VP8:
      if(!case_info->codec)  case_info->codec = DEC_MODE_VP8;
      sprintf(f, "%s", "vp8");
      break;
    case DEC_VP9:
      if(!case_info->codec)  case_info->codec = DEC_MODE_VP8;
      sprintf(f, "%s", "vp9");
      break;
    case DEC_HEVC:
      if(!case_info->codec)  case_info->codec = DEC_MODE_HEVC;
      sprintf(f, "%s", "hevc");
      break;
    case DEC_H264:
      sprintf(f, "%s", "h264"); break;
    case DEC_AVS:
      if(!case_info->codec)  case_info->codec = DEC_MODE_AVS;
      sprintf(f, "%s", "avs");
      break;
    case DEC_AVS2:
      if(!case_info->codec)  case_info->codec = DEC_MODE_AVS2;
      sprintf(f, "%s", "avs2");
      break;
    case DEC_AV1:
      if(!case_info->codec)  case_info->codec = DEC_MODE_AV1;
      sprintf(f, "%s", "av1");
      break;
    case DEC_JPEG:
      if(!case_info->codec)  case_info->codec = DEC_MODE_JPEG;
      sprintf(f, "%s", "jpeg");
      break;
    case DEC_VC1:
      if(!case_info->codec)  case_info->codec = DEC_MODE_VC1;
      sprintf(f, "%s", "vc1");
      break;
    case DEC_RV:
      if(!case_info->codec)  case_info->codec = DEC_MODE_RV;
      sprintf(f, "%s", "rv");
      break;
    case DEC_VVC:
      if(!case_info->codec)  case_info->codec = DEC_MODE_VVC;
      sprintf(f, "%s", "vvc");
      break;
	  case DEC_AVS3:
      if(!case_info->codec)  case_info->codec = DEC_MODE_AVS3;
      sprintf(f, "%s", "avs3");
      break;
    case DEC_PNG:
      if(!case_info->codec)  case_info->codec = DEC_MODE_PNG;
      sprintf(f, "%s", "png");
      break;
  }
}

static void GetFrameTypeString(CaseInfo* case_info, char* s) {
  u32 i = 0, j = 0;
  for(i=0; i<20 && j<case_info->frame_num && j<10; i++) {
    if(case_info->codec == DEC_JPEG) break;
    switch(case_info->frame_type[i]) {
      case I_FRAME: strcat(s, "I,"); break;
      case B_FRAME: strcat(s, "B,"); break;
      case P_FRAME: strcat(s, "P,"); break;
      case GB_FRAME: strcat(s, "GB,"); break;
      case F_FRAME: strcat(s, "F,"); break;
      case S_FRAME: strcat(s, "S,"); break;
      case G_FRAME: strcat(s, "G,"); break;
      case BI_FRAME: strcat(s, "BI,"); break;
      case FIELD_I_I: strcat(s, "[I,I],"); break;
      case FIELD_I_P: strcat(s, "[I,P],"); break;
      case FIELD_P_I: strcat(s, "[I,P],"); break;
      case FIELD_P_P: strcat(s, "[P,P],"); break;
      case FIELD_B_B: strcat(s, "[B,B],"); break;
      case FIELD_BI_B: strcat(s, "[BI,B],"); break;
      case FIELD_B_BI: strcat(s, "[B,BI],"); break;
      case FIELD_BI_BI: strcat(s, "[BI,BI],"); break;
      case I_FIELED_0:
        if (i < 19  && case_info->frame_type[i+1] > B_FIELED_0 )
          strcat(s, "[I:");
        else
          strcat(s, "I,");
        break;
      case P_FIELED_0:
        if (i < 19 && case_info->frame_type[i+1] > B_FIELED_0 )
          strcat(s, "[P:");
        else
          strcat(s, "P,");
        break;
      case B_FIELED_0:
        if (i < 19 && case_info->frame_type[i+1] > B_FIELED_0 )
          strcat(s, "[B:");
        else
          strcat(s, "B,");
        break;
      case I_FIELED_1: strcat(s, "I],"); break;
      case P_FIELED_1: strcat(s, "P],"); break;
      case B_FIELED_1: strcat(s, "B],"); break;
    }
    if(case_info->frame_type[i] >= I_FIELED_1 || case_info->frame_type[i] < I_FIELED_0)
      j++;
  }
  s[strlen(s)-1] = '\0';
}

static void GetChromaSampleTypeString(CaseInfo* case_info, char* p) {
  if(case_info->codec == DEC_MODE_PNG) {
    switch(case_info->chroma_format_id) {
      case 0: sprintf(p, "%s", "YUV400"); break;
      case 1: sprintf(p, "%s", "RGB565"); break;
      case 2:
      case 3: sprintf(p, "%s", "RGB888"); break;
      case 4: sprintf(p, "%s", "YUV400_A"); break;
      case 5: sprintf(p, "%s", "ARGB565"); break;
      case 6: sprintf(p, "%s", "ARGB888"); break;
    }
  } else if(case_info->codec == DEC_MODE_JPEG){
    switch(case_info->chroma_format_id) {
      case 0: sprintf(p, "%s", "YUV400"); break;
      case 1: sprintf(p, "%s", "YUV420"); break;
      case 2: sprintf(p, "%s", "YUV422"); break;
      case 3: sprintf(p, "%s", "YUV411"); break;
      case 4: sprintf(p, "%s", "YUV440"); break;
      case 5: sprintf(p, "%s", "YUV444"); break;
      default: sprintf(p, "%s", "NOT_DEFINE"); break;
    }
  } else {
    switch(case_info->chroma_format_id) {
      case 0: sprintf(p, "%s", "YUV400"); break;
      case 1: sprintf(p, "%s", "YUV420"); break;
      case 2: sprintf(p, "%s", "YUV422"); break;
      case 3: sprintf(p, "%s", "YUV444"); break;
      default: sprintf(p, "%s", "NOT_DEFINE"); break;
    }
  }
}

void VCDecInfoCollect(CaseInfo* case_info){
  FILE* cp = fopen("caseprint.txt", "wb");
  if(cp == NULL)
    return;

  char f[10];
  u32 num;
  char p[12],s[100];
  DWLmemset(s, 0, 100);

  GetFormatString(case_info, f);

  GetFrameTypeString(case_info, s);

  GetChromaSampleTypeString(case_info, p);

  fprintf(cp, "%s|%u|%s%s%s|%u|%u|%u|%u|%d|%u|%u|%s%u,%u%s|%u|%u|%s|",
          f, case_info->codec,"[", s, "]", case_info->frame_num > 0? case_info->frame_num : 1, case_info->scan_count,
          case_info->min_cb_size, case_info->max_cb_size, case_info->bit_depth,
          case_info->display_width, case_info->display_height, "(",case_info->crop_x, case_info->crop_y, ")",
          case_info->decode_width, case_info->decode_height, case_info->frame_num > 0? p : " " );

  num = case_info->frame_num > 10 ? 10 : case_info->frame_num;
  WriteInfo(case_info->slice_num, num, cp);
  WriteInfo(case_info->ppin_luma_size, num, cp);
  WriteInfo(case_info->bit_depth_y_minus8, num, cp);
  WriteInfo(case_info->bit_depth_c_minus8, num, cp);
  WriteInfo(case_info->blackwhite_e, num, cp);
  WriteInfo(case_info->num_tile_cols_8k, num, cp);
  WriteInfo(case_info->fieldpic_flag, num, cp);
  WriteInfo(case_info->fieldmode, num, cp);

  if(case_info->frame_num)
    fprintf(cp,"%u|",case_info->bitrate/case_info->frame_num);
  else
    fprintf(cp,"%s|", "invalid");

  fprintf(cp, "%s|%s|%s|%s|%s|%s%s%s%s%s%s%s%s%s%s%s", case_info->crop_flag? "x":" ", case_info->chroma_flag? "x":" ",
          case_info->depth_flag?  "x":" ", case_info->resolution_flag? "x":" ", case_info->show_existing_frame? "x":" ",
          case_info->interlace_flag? "interlace ":"", case_info->intrabc_flag? "intrabc ":"",
          case_info->tile_flag? "tile ":"", case_info->aso_flag? "aso ":"",
          case_info->fmo_flag? "fmo ":"", case_info->pjpeg_flag? "pjpeg ":"",
          case_info->thumb_flag? "thumbnail ":"",
          case_info->interintra ? "interintra ":"", case_info->palette_mode ? "palette_mode ":"",
          case_info->filter_intra_pred ? "filter_intra_pred ":"", case_info->intra_edge_filter? "intra_edge_filter ":"");

  if(!case_info->interlace_flag && !case_info->intrabc_flag && !case_info->tile_flag && !case_info->aso_flag
     && !case_info->fmo_flag && !case_info->pjpeg_flag && !case_info->thumb_flag && !case_info->cavlc_flag
     && !case_info->interintra && !case_info->palette_mode && !case_info->filter_intra_pred
     && !case_info->intra_edge_filter)
     fprintf(cp, "%s", " ");
  if(cp) fclose(cp);
}

