#define SW_STREAM_H_

struct StrmData {
  const u8 *strm_buff_start; /* pointer to start of stream buffer */
  const u8 *strm_curr_pos;   /* current read address in stream buffer */
  u32 bit_pos_in_word;       /* bit position in stream buffer byte */
  u32 strm_buff_size;        /* size of stream buffer (bytes) */
  u32 strm_data_size;        /* size of stream data (bytes) */
  u32 strm_buff_read_bits;   /* number of bits read from stream buffer */
  u32 remove_emul3_byte;     /* signal the pre-removal of emulation prevention 3
                    bytes */
  u32 emul_byte_count; /* counter incremented for each removed byte */
  u32 is_rb;               /* ring buffer used? */
  u32 remove_avs_fake_2bits;     /* = 1 to remove 2-bit '10' for  fake start code  */
  struct strmInfo *stream_info;
};

typedef u8 SwReadByteFn(const u8 *p, u32 size, struct strmInfo *stream_info);
u32 SwGetBits(struct StrmData *stream, u32 num_bits);
u32 SwGetBits32(struct StrmData *stream);
u32 SwGetBitsUnsignedMax(struct StrmData *stream, u32 max_value);
u32 SwShowBits(struct StrmData *stream, u32 num_bits);
u32 SwFlushBits(struct StrmData *stream, u32 num_bits);
u32 SwIsByteAligned(const struct StrmData *);
u8 SwNoLatencyReadByte(const u8 *p, u32 size, struct strmInfo *stream_info);
u8 SwLowLatencyReadByte(const u8 *p, u32 buf_size, struct strmInfo *stream_info);
u32 SWLowLatencyIsEndOfStream(const u8 *strm_curr_pos, u32 num_bits, u32 buf_size, struct strmInfo *stream_info);
SwReadByteFn *SwGetReadByteFunc(struct strmInfo *stream_info);
void SwUpdateStrmDataSize(struct StrmData *stream);
#ifdef STREAM_TRACE
void SwStreamTraceOpen();
void SwStreamTrace(char *format, ...);
void SwStreamTraceClose();
#else
#define SwStreamTraceOpen()
#define SwStreamTrace(format, ...)
#define SwStreamTraceClose()
#endif
u32 SwCountLeadingZeros(u32 value, u32 length);
u32 SwNumBits(u32 value);
u8* SwTurnAround(const u8 * strm, const u8* buf, u8* tmp_buf, u32 buf_size, u32 num_bits, struct strmInfo *stream_info);

/* utils for u(v) */
static inline int floorLog2(u32 x) {
  if (x == 0)
  {
    // note: ceilLog2() expects -1 as return value
    return -1;
  }
#ifdef __GNUC__
  return 31 - __builtin_clz(x);
#else
#ifdef _MSC_VER
  unsigned long r = 0;
  _BitScanReverse(&r, x);
  return r;
#else
  int result = 0;
  if (x & 0xffff0000)
  {
    x >>= 16;
    result += 16;
  }
  if (x & 0xff00)
  {
    x >>= 8;
    result += 8;
  }
  if (x & 0xf0)
  {
    x >>= 4;
    result += 4;
  }
  if (x & 0xc)
  {
    x >>= 2;
    result += 2;
  }
  if (x & 0x2)
  {
    x >>= 1;
    result += 1;
  }
  return result;
#endif
#endif
}

static inline int ceilLog2(u32 x)
{
  return (x==0) ? -1 : floorLog2(x - 1) + 1;
}

#define READ_CODE(stream, n, syntax, str) do { \
  u32 ucode = SwGetBits(stream, (n)); \
  if (ucode == END_OF_STREAM) return(HANTRO_NOK); \
  SwStreamTrace("%s : %d", str, ucode); \
  syntax = ucode; \
} while (0)

#define READ_CODE_NO_TRC(stream, n, syntax) do { \
  u32 ucode = SwGetBits(stream, (n)); \
  if (ucode == END_OF_STREAM) return(HANTRO_NOK); \
  syntax = ucode; \
} while (0)

#define READ_FLAG(stream, syntax, str) READ_CODE(stream, 1, syntax, str)

#define READ_CODE_ARGS(stream, n, syntax, str, ...) do { \
  u32 ucode = SwGetBits(stream, (n)); \
  char tmp_str[128]; \
  if (ucode == END_OF_STREAM) return(HANTRO_NOK); \
  snprintf(tmp_str, 128, str, ##__VA_ARGS__); \
  SwStreamTrace("%s : %d", tmp_str, ucode); \
  syntax = ucode; \
} while (0)

#define READ_FLAG_ARGS(stream, syntax, str, ...) READ_CODE_ARGS(stream, 1, syntax, str, ##__VA_ARGS__)

#define CHECK_SYNTAX(cond, msg) do { \
  if (cond) { \
    ERROR_PRINT(msg); \
    return (HANTRO_NOK); \
  } \
} while (0)

#define CHECK_SYNTAX_WARN(cond, msg) do { \
  if (cond) { \
    ERROR_PRINT_WARN(msg); \
  } \
} while (0)

#define CHECK_SYNTAX_2(cond, msg) do { \
  if (cond) { \
    ERROR_PRINT(msg); \
    return; \
  } \
} while (0)

#define CHECK_ALLOCATION(cond, msg, target) do { \
  if (cond) { \
    ERROR_PRINT(msg); \
    goto target; \
  } \
} while (0)

//#define STREAM_TRACE

#ifdef STREAM_TRACE
static FILE *trace_stream_txt = NULL;
char flushed_bit_string[10*1024];
#endif

static const u8* SwRingBufferProtect(const u8 *strm, int size, struct StrmData *stream, u8 turn_around_flag) {
  const u8 *p = NULL;

  ASSERT(strm);
  ASSERT(stream);

  if (strm != stream->strm_curr_pos && turn_around_flag) {
    /* SwTurnAround has been called. */
    p = strm + size;
    return p;
  }

  if (size < 0)
    p = (strm + size >= stream->strm_buff_start ? (strm + size) : (strm + size + stream->strm_buff_size));
  else if (size > 0) {
    p = (strm + size <= stream->strm_buff_start + stream->strm_buff_size) ?
        (strm + size) : (strm + size - stream->strm_buff_size);
  }
  else
    p = strm;
  return p;
}

u32 SwGetBits(struct StrmData *stream, u32 num_bits) {

  u32 out;

  ASSERT(stream);
  ASSERT(num_bits <= 32);

  if (num_bits == 0) return 0;

  out = SwShowBits(stream, 32) >> (32 - num_bits);

  if (SwFlushBits(stream, num_bits) == HANTRO_OK) {
    return (out);
  } else {
    return (END_OF_STREAM);
  }
}

u32 SwGetBits32(struct StrmData *stream) {

  u32 out;

  ASSERT(stream);

  out = SwShowBits(stream, 32);

  (void)SwFlushBits(stream, 32);

  return out;
}

u32 SwGetBitsUnsignedMax(struct StrmData *stream, u32 max_value) {
  i32 bits = 0;
  u32 num_values = max_value;
  u32 value;

  /* Bits for unsigned value */
  if (num_values > 1) {
    num_values--;
    while (num_values > 0) {
      bits++;
      num_values >>= 1;
    }
  }

  value = SwGetBits(stream, bits);
  return (value > max_value) ? max_value : value;
}

u32 SwShowBits(struct StrmData *stream, u32 num_bits) {

  i64 bits;
  u32 out, out_bits;
  u32 tmp_read_bits;
  const u8 *strm;
  SwReadByteFn *fn_read_byte;
  /* used to copy stream data when ringbuffer turnaround */
  u8 tmp_strm_buf[32], *tmp;
  u8 turn_around_flag = FALSE;

  ASSERT(stream);
  ASSERT(stream->strm_curr_pos);
  ASSERT(stream->bit_pos_in_word < 8);
  ASSERT(stream->bit_pos_in_word == (stream->strm_buff_read_bits & 0x7));
  ASSERT(num_bits <= 32);

  strm = stream->strm_curr_pos;
  fn_read_byte = SwGetReadByteFunc(stream->stream_info);

  /* bits left in the buffer */
  SwUpdateStrmDataSize(stream);

  bits = (i64)stream->strm_data_size * 8 - (i64)stream->strm_buff_read_bits;
  if (!bits || bits < 0) {
    return (END_OF_STREAM);
  }

  if (stream->is_rb)
    tmp = SwTurnAround(stream->strm_curr_pos, stream->strm_buff_start,
                       tmp_strm_buf, stream->strm_buff_size,
                       MIN(bits, num_bits + stream->bit_pos_in_word + 32), stream->stream_info);
  else
    tmp = NULL;

  if (tmp != NULL) {
    strm = tmp;
    fn_read_byte = SwNoLatencyReadByte;
    turn_around_flag = TRUE;
  }

  if (!stream->remove_emul3_byte) {

    out = out_bits = 0;
    tmp_read_bits = stream->strm_buff_read_bits;

    if (stream->bit_pos_in_word) {
      out = (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << (24 + stream->bit_pos_in_word);
      strm++;
      out_bits = 8 - stream->bit_pos_in_word;
      bits -= out_bits;
      tmp_read_bits += out_bits;
    }

    while (bits && out_bits < num_bits) {

      /* check emulation prevention byte */
      if (tmp_read_bits >= 16 &&
          (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x3) {
        strm++;
        tmp_read_bits += 8;
        bits -= 8;
        /* emulation prevention byte shall not be the last byte of the
         * stream */
        if (bits <= 0) break;
      }

      tmp_read_bits += 8;

      if (out_bits <= 24) {
        out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << (24 - out_bits);
        strm++;
      } else {
        out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) >> (out_bits - 24);
        strm++;
      }

      out_bits += 8;
      bits -= 8;
    }

    return (out >> (32 - num_bits));

  }
  else if(stream->remove_avs_fake_2bits)
  {
    out = out_bits = 0;
    tmp_read_bits = stream->strm_buff_read_bits;

    if (stream->bit_pos_in_word) {
      out = (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << (24 + stream->bit_pos_in_word);

      /* check emulation prevention byte */
      if (tmp_read_bits >= 16 &&
          (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x2) {
        strm++;
        tmp_read_bits += 8 - stream->bit_pos_in_word;
        bits -= 8 - stream->bit_pos_in_word;

        out_bits = 8 - stream->bit_pos_in_word - 2;

        out &=~((1<<(32-out_bits))-1);
      }
      else
      {
        strm++;
        tmp_read_bits += 8 - stream->bit_pos_in_word;
        bits -= 8 - stream->bit_pos_in_word;
        out_bits = 8 - stream->bit_pos_in_word;
      }

    }

    while (bits && out_bits < num_bits) {

      /* check emulation prevention byte */
      if (tmp_read_bits >= 16 &&
          (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x2) {

        if (out_bits <= 24) {
          out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << (24 - out_bits);
        } else {
          out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) >> (out_bits - 24);
        }

        strm++;
        tmp_read_bits += 8;
        bits -= 8;
        out_bits += 6;
        out &=~((1<<(32-out_bits))-1);
      }
      else
      {
          if (out_bits <= 24) {
            out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << (24 - out_bits);
          } else {
            out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) >> (out_bits - 24);
          }

          strm++;
          tmp_read_bits += 8;
          bits -= 8;
          out_bits += 8;
      }
    }

    return (out >> (32 - num_bits));
  }
  else {
    u32 shift;

    /* at least 32-bits in the buffer */
    if (bits >= 32) {
      u32 bit_pos_in_word = stream->bit_pos_in_word;

      out = ((u32)(fn_read_byte(SwRingBufferProtect(strm, 3, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info))) |
            ((u32)(fn_read_byte(SwRingBufferProtect(strm, 2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) << 8) |
            ((u32)(fn_read_byte(SwRingBufferProtect(strm, 1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) << 16) |
            ((u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << 24);

      if (bit_pos_in_word) {
        out <<= bit_pos_in_word;
        out |= (u32)(fn_read_byte(SwRingBufferProtect(strm, 4, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) >> (8 - bit_pos_in_word);
      }

      return (out >> (32 - num_bits));
    }
    /* at least one bit in the buffer */
    else if (bits > 0) {
      shift = (i32)(24 + stream->bit_pos_in_word);
      out = (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << shift;
      strm++;
      bits -= (i32)(8 - stream->bit_pos_in_word);
      while (bits > 0) {
        shift -= 8;
        out |= (u32)(fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) << shift;
        strm++;
        bits -= 8;
      }
      return (out >> (32 - num_bits));
    } else
      return (END_OF_STREAM);
  }
}

u32 SwFlushBits(struct StrmData *stream, u32 num_bits) {
  u32 bytes_left;
  const u8 *strm, *strm_bak;
  u8 tmp_strm_buf[32], *tmp;
  i64 bits;
  u32 out_bits;
  u32 tmp_read_bits;
  SwReadByteFn *fn_read_byte;
  u8 turn_around_flag = FALSE;

  ASSERT(stream);
  ASSERT(stream->strm_buff_start);
  ASSERT(stream->strm_curr_pos);
  ASSERT(stream->bit_pos_in_word < 8);
  ASSERT(stream->bit_pos_in_word == (stream->strm_buff_read_bits & 0x7));

  strm = stream->strm_curr_pos;
  fn_read_byte = SwGetReadByteFunc(stream->stream_info);

  SwUpdateStrmDataSize(stream);

  bits = (i64)stream->strm_data_size * 8 - (i64)stream->strm_buff_read_bits;

  if (!bits || bits < 0) {
    return (END_OF_STREAM);
  }

  /* used to copy stream data when ringbuffer turnaround */
  if (stream->is_rb)
    tmp = SwTurnAround(stream->strm_curr_pos, stream->strm_buff_start,
                       tmp_strm_buf, stream->strm_buff_size,
                       MIN(bits, num_bits + stream->bit_pos_in_word + 32), stream->stream_info);
  else
    tmp = NULL;

  if (tmp != NULL) {
    strm = tmp;
    fn_read_byte = SwNoLatencyReadByte;
    turn_around_flag = TRUE;
  }

#ifdef STREAM_TRACE
  if (trace_stream_txt) {
    u32 i, bits, tmp_num_bits;
    tmp_num_bits = num_bits;
    flushed_bit_string[0] = '\0';
    while (tmp_num_bits > 32) {
      tmp_num_bits -= 32;
      bits = SwShowBits(stream, 32);
      for (i = 0; i < 32; i++) {
        strcat(flushed_bit_string, (bits & 0x80000000) ? "1" : "0");
        bits <<= 1;
      }
    }
    ASSERT(tmp_num_bits <= 32);
    bits = SwShowBits(stream, tmp_num_bits);
    bits <<= 32 - tmp_num_bits;
    for (i = 0; i < tmp_num_bits; i++) {
      strcat(flushed_bit_string, (bits & 0x80000000) ? "1" : "0");
      bits <<= 1;
    }
  }
#endif

  if (!stream->remove_emul3_byte) {
    if ((stream->strm_buff_read_bits + num_bits) >
        (8 * stream->strm_data_size)) {
      stream->strm_buff_read_bits = 8 * stream->strm_data_size;
      stream->bit_pos_in_word = 0;
      stream->strm_curr_pos = stream->strm_buff_start + stream->strm_buff_size;
      return (END_OF_STREAM);
    } else {
      bytes_left =
        (8 * stream->strm_data_size - stream->strm_buff_read_bits) / 8;
      if(tmp != NULL)
        strm = tmp;
      else
        strm = stream->strm_curr_pos;
      strm_bak = strm;

      if (stream->bit_pos_in_word) {
        if (num_bits < 8 - stream->bit_pos_in_word) {
          stream->strm_buff_read_bits += num_bits;
          stream->bit_pos_in_word += num_bits;
          return (HANTRO_OK);
        }
        num_bits -= 8 - stream->bit_pos_in_word;
        stream->strm_buff_read_bits += 8 - stream->bit_pos_in_word;
        stream->bit_pos_in_word = 0;
        strm++;

        if (stream->strm_buff_read_bits >= 16 && bytes_left &&
            (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
            (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
            (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x3) {
          strm++;
          stream->strm_buff_read_bits += 8;
          bytes_left--;
          stream->emul_byte_count++;
        }
      }

      while (num_bits >= 8 && bytes_left) {
        if (bytes_left > 2 && (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0 &&
            (fn_read_byte(SwRingBufferProtect(strm, 1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0 &&
            (fn_read_byte(SwRingBufferProtect(strm, 2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) <= 1) {
          /* trying to flush part of start code prefix -> error */
          /* need consum data: will hang if not consumed. */
          strm++;
          stream->strm_buff_read_bits += 8;
          bytes_left--;
          return (HANTRO_NOK);
        }

        strm++;
        stream->strm_buff_read_bits += 8;
        bytes_left--;

        /* check emulation prevention byte */
        if (stream->strm_buff_read_bits >= 16 && bytes_left &&
            (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
            (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info))== 0x0 &&
            (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x3) {
          strm++;
          stream->strm_buff_read_bits += 8;
          bytes_left--;
          stream->emul_byte_count++;
        }
        num_bits -= 8;
      }

      if (num_bits && bytes_left) {
        if (bytes_left > 2 && (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0 &&
            (fn_read_byte(SwRingBufferProtect(strm, 1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0 &&
            (fn_read_byte(SwRingBufferProtect(strm, 2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) <= 1) {
          /* trying to flush part of start code prefix -> error */
          /* need consum data: will hang if not consumed. */
          strm++;
          stream->strm_buff_read_bits += 8;
          bytes_left--;
          return (HANTRO_NOK);
        }

        stream->strm_buff_read_bits += num_bits;
        stream->bit_pos_in_word = num_bits;
        num_bits = 0;
      }

      stream->strm_curr_pos += strm - strm_bak;
      if (stream->is_rb && stream->strm_curr_pos >= (stream->strm_buff_start + stream->strm_buff_size))
        stream->strm_curr_pos -= stream->strm_buff_size;

      if (num_bits)
        return (END_OF_STREAM);
      else
        return (HANTRO_OK);
    }
  }
  else if(stream->remove_avs_fake_2bits)
  {
    u32 bit_shift=0;
    u32 bytes_shift = 0;
    u32 bit_left = 0;
    out_bits = 0;
    tmp_read_bits = stream->strm_buff_read_bits;

    do
    {
      /* check emulation prevention byte */
      if (tmp_read_bits >= 16 &&
          (fn_read_byte(SwRingBufferProtect(strm, -2, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(SwRingBufferProtect(strm, -1, stream, turn_around_flag), stream->strm_buff_size, stream->stream_info)) == 0x0 &&
          (fn_read_byte(strm, stream->strm_buff_size, stream->stream_info)) == 0x2) {
        bit_left = (8 - (tmp_read_bits%8));
        if(num_bits>=out_bits+bit_left-2)
        {
            bit_shift +=2;
            out_bits += bit_left-2;
            strm++;
            tmp_read_bits += bit_left;
            bits -= bit_left;
        }
        else
        {
            tmp_read_bits += num_bits-out_bits;
            bits -= num_bits-out_bits;
            out_bits = num_bits;
        }

      }
      else
      {
        bit_left = (8 - (tmp_read_bits%8));
        if(num_bits>=out_bits+bit_left)
        {
            out_bits += bit_left;
            strm++;
            tmp_read_bits += bit_left;
            bits -= bit_left;
        }
        else
        {
            tmp_read_bits += num_bits-out_bits;
            bits -= num_bits-out_bits;
            out_bits = num_bits;
        }
      }

    }while(out_bits < num_bits && bits > 0);

    bytes_shift = (stream->bit_pos_in_word + num_bits + bit_shift) >> 3;
    stream->strm_buff_read_bits += num_bits + bit_shift;
    stream->bit_pos_in_word = stream->strm_buff_read_bits & 0x7;
    if ((stream->strm_buff_read_bits) <= (8 * stream->strm_data_size)) {
      stream->strm_curr_pos += bytes_shift;
      if (stream->is_rb && stream->strm_curr_pos >= (stream->strm_buff_start + stream->strm_buff_size))
        stream->strm_curr_pos -= stream->strm_buff_size;
      return (HANTRO_OK);
    } else
      return (END_OF_STREAM);
  }
  else {
    u32 bytes_shift = (stream->bit_pos_in_word + num_bits) >> 3;
    stream->strm_buff_read_bits += num_bits;
    stream->bit_pos_in_word = stream->strm_buff_read_bits & 0x7;
    if ((stream->strm_buff_read_bits) <= (8 * stream->strm_data_size)) {
      stream->strm_curr_pos += bytes_shift;
      if (stream->is_rb && stream->strm_curr_pos >= (stream->strm_buff_start + stream->strm_buff_size))
        stream->strm_curr_pos -= stream->strm_buff_size;
      return (HANTRO_OK);
    } else
      return (END_OF_STREAM);
  }
}

u32 SwIsByteAligned(const struct StrmData *stream) {

  if (!stream->bit_pos_in_word)
    return (HANTRO_TRUE);
  else
    return (HANTRO_FALSE);
}

u8 SwNoLatencyReadByte(const u8 *p, u32 size, struct strmInfo *stream_info) {
  UNUSED(size);
  UNUSED(stream_info);
  return SwReadByte(p);
}

u8 SwLowLatencyReadByte(const u8 *p, u32 buf_size, struct strmInfo *stream_info) {
  u32 len = 0;
  if (!stream_info)
    return 0xFF;
  do {
    if (p >= stream_info->strm_vir_start_addr)
      len = p - stream_info->strm_vir_start_addr;
    else
      len = buf_size + p - stream_info->strm_vir_start_addr;
    sched_yield();
  } while ((len >= stream_info->send_len) && !stream_info->last_flag);

  if (stream_info->last_flag && len > stream_info->send_len)
    return 0xFF;
  return SwReadByte(p);
}

u32 SWLowLatencyIsEndOfStream(const u8 *strm_curr_pos, u32 num_bits, u32 buf_size, struct strmInfo *stream_info) {
  const u8 *p;
  u32 len = 0;
  u32 byte_shift = 0;
  if (!stream_info)
    return 0xFF;
  byte_shift = num_bits >> 3;
  byte_shift += ((num_bits % 8) > 0) ? 1 : 0;
  p = strm_curr_pos + byte_shift;
  do {
    if (p >= stream_info->strm_vir_start_addr)
      len = p - stream_info->strm_vir_start_addr;
    else
      len = buf_size + p - stream_info->strm_vir_start_addr;
    sched_yield();
  } while ((len > stream_info->send_len) && !stream_info->last_flag);

  if (stream_info->last_flag && len > stream_info->send_len)
    return 0xFFFFFFFFU;
  return 0;
}

SwReadByteFn *SwGetReadByteFunc(struct strmInfo *stream_info) {
  if (stream_info && stream_info->low_latency) {
    return SwLowLatencyReadByte;
  }
  return SwNoLatencyReadByte;
}

void SwUpdateStrmDataSize(struct StrmData *stream){
  if (stream->stream_info && stream->stream_info->low_latency && stream->stream_info->last_flag) {
    if (stream->strm_buff_read_bits == stream->strm_data_size * 8) {
      stream->strm_data_size = 0;
    } else {
      if (stream->strm_curr_pos >= stream->stream_info->strm_vir_start_addr)
        stream->strm_data_size = stream->stream_info->send_len - (u32)(stream->strm_curr_pos - stream->stream_info->strm_vir_start_addr);
      else
        stream->strm_data_size = stream->stream_info->send_len - (u32)(stream->strm_curr_pos + stream->strm_buff_size - stream->stream_info->strm_vir_start_addr);
    }
    stream->strm_data_size += stream->strm_buff_read_bits / 8;
  }
}

#ifdef STREAM_TRACE
void SwStreamTraceOpen() {
  /* Code */
  if (!trace_stream_txt) {
    trace_stream_txt = fopen("sw_stream.txt", "w");
  }
}

void SwStreamTrace(char *format, ...) {

  /* Variables */
  va_list ap;

  char tmp[128], final_format[128] = "", *ptr, length_string[13] = {0};
  u32 i, length;

  /* Code */
  if (trace_stream_txt) {
    va_start(ap, format);

    strcpy(tmp, format);
    i = 0;
    ptr = strtok(tmp, "%");
    if (ptr == tmp) {
      /* No "%x" found in input format, which means just to print a simple string */
      fprintf(trace_stream_txt,"%s\n", ptr);
	  va_end(ap);
      return;
    }
    while (ptr != NULL) {
      sprintf(length_string, "%s-%d", "%", i > 0 ? 6 : 64);
      strcat(final_format, length_string);
      strcat(final_format, ptr);
      ptr = strtok(NULL, "%");
      i++;
    }

    vfprintf(trace_stream_txt, final_format, ap);

    /* print empty fields if only two or three fields printed */
    while (i < 4) {
      i++;
      fprintf(trace_stream_txt,"%-6s", "");
    }

    fprintf(trace_stream_txt,"%-17s", flushed_bit_string);

    /* print flushed bit string length */
    length = strlen(flushed_bit_string);
    if (length) {
      sprintf(length_string, "[%u]", length);
      fprintf(trace_stream_txt,"%s", length_string);
    }

    fprintf(trace_stream_txt, "\n");
    fflush(trace_stream_txt);

    /* reset flushed bit string */
    flushed_bit_string[0] = '\0';

    va_end(ap);
  }
}

void SwStreamTraceClose() {
  if (trace_stream_txt) {
    fclose(trace_stream_txt);
    trace_stream_txt = NULL;
  }
}
#endif

u32 SwCountLeadingZeros(u32 value, u32 length) {

  u32 zeros = 0;
  u32 mask = 1 << (length - 1);

  ASSERT(length <= 32);

  while (mask && !(value & mask)) {
    zeros++;
    mask >>= 1;
  }
  return (zeros);
}

u32 SwNumBits(u32 value) {
  return 32 - SwCountLeadingZeros(value, 32);
}

/*
* return a pointer which points to strm and guarantee there're at least 2 bytes space prior to the pointer for checking emulation prevention byte.
* like x x p x x x x x, p points to strm.
* there're 3 turn around types, respectively
* 0: no turn around.
* 1: turn around and strm is away from buf start more than (>=) 2 bytes, like x x x x s x x x, s is strm
* 2: turn around but strm is away from buf start less than (<) 2 bytes, like x s x x x x, s is strm.
* type 2 is used to handle corner case when emulation prevention byte (00 00 03) is splited by buf end
*/
u8* SwTurnAround(const u8 * strm, const u8* buf, u8* tmp_buf, u32 buf_size, u32 num_bits, struct strmInfo *stream_info) {
  u32 bytes = (num_bits+7)/8;
  u32 turn_around_type = 0;
  SwReadByteFn *fn_read_byte;

  if((strm + bytes) > (buf + buf_size))
    turn_around_type = 1;

  if(strm - buf < 2)  {
    ASSERT(turn_around_type == 0);
    turn_around_type = 2;
  }

  if(turn_around_type == 0) {
    return NULL;
  } else if(turn_around_type == 1) {
    i32 i;
    u32 bytes_left = (u32)((buf + buf_size) - strm);

    if (stream_info && stream_info->low_latency)
      stream_info->is_back_to_buffer_begin = 1;
    fn_read_byte = SwGetReadByteFunc(stream_info);

    /* turn around */
    for(i = -3; i < (i32)0; i++) {
      tmp_buf[3 + i] = SwPrivateAreaReadByte(strm + i);
    }
    for(i = 0; i < (i32)bytes_left; i++) {
      tmp_buf[3 + i] = fn_read_byte(strm + i, buf_size, stream_info);
    }
    /*turn around point*/
    for(i = 0; i < (i32)(bytes - bytes_left); i++) {
      tmp_buf[3 + bytes_left + i] = fn_read_byte(buf + i, buf_size, stream_info);
    }

    return tmp_buf+3;
  } else {
    i32 i;
    u32 left_byte = (u32)(strm - buf);

    fn_read_byte = SwGetReadByteFunc(stream_info);

    /* turn around */
    for(i = 0; i < 2; i++) {
      tmp_buf[i] = SwPrivateAreaReadByte(buf + buf_size - 2 + i);
    }

    /*turn around point*/
    for(i = 0; i < (i32)(bytes + left_byte); i++) {
      tmp_buf[i + 2] = fn_read_byte(buf + i, buf_size, stream_info);
    }

    return (tmp_buf + 2 + left_byte);
  }
}

