  ImageData image;
  ScanInfo scan;
  DecInfo info;
  // HuffmanTables vlc;
  // QuantTables quant;
  u32 tmp_data[64];

  u32 max_supported_slice_size;
  JpegAsicBuffers asic_buff;
  const void *dwl;    /* DWL instance */
