  u32  fb_stat[MAX_FRAME_NUMBER];
  Png_OutElement out_fifo[MAX_FRAME_NUMBER];
  int wr_id;
  int rd_id;
  int num_out;
  u32 b_initialized;
  u32 end_of_stream;

