  u32 ext_buffer_num;
  u32 buffer_index;
  u32 tot_buffers;
  u64 n_ext_buf_size;        // size of external buffers added
  u32 buffer_queue_index;
  u32 realloc_buffer;
  u32 use_adaptive_buffers;
  u32 cur_out_ext_buf_index;
