  Png_FrameBufferList fb_list;
  PngDecHdrs Hdrs;
  enum Lz77Mode lz77_mode;
  u32 lz77_tail_size; //for lz77_mode==1, lz77_tail_size = (origin_size % 1280) ? (origin_size % 1280) : 1280.
  u32 channels;
